// Parse WhatsApp incoming message
const body = $input.first().json.body || $input.first().json;

let phoneNumber = '';
let message = '';
let contactName = 'Client';
let source = 'whatsapp';

// Handle different webhook formats
if (body.entry) {
  // Meta WhatsApp Cloud API format
  try {
    const entry = body.entry[0];
    const changes = entry.changes[0];
    const value = changes.value;

    if (value.messages && value.messages.length > 0) {
      const msg = value.messages[0];
      phoneNumber = msg.from;
      message = msg.text?.body || msg.button?.text || 'Hello';
      contactName = value.contacts?.[0]?.profile?.name || 'Client';
    } else {
      // Not a message event, skip
      return [{ json: { skip: true } }];
    }
  } catch(e) {
    return [{ json: { skip: true, error: e.message } }];
  }
} else if (body.From) {
  // Twilio format
  phoneNumber = body.From.replace('whatsapp:', '');
  message = body.Body;
  contactName = 'Client';
}

return [{
  json: {
    phoneNumber,
    message,
    contactName,
    source,
    sessionId: `wa_${phoneNumber}`,
    timestamp: new Date().toISOString()
  }
}];

// Parse Meta Ads Lead Form submission
const body = $input.first().json.body || $input.first().json;

let leadData = {};

// Meta Lead Gen Form format
if (body.entry) {
  const entry = body.entry[0];
  const change = entry.changes[0];
  const leadgenId = change.value.leadgen_id;
  const formId = change.value.form_id;
  const pageId = change.value.page_id;

  leadData = {
    leadgenId,
    formId,
    pageId,
    adId: change.value.ad_id,
    source: 'meta_ads'
  };
} else {
  // Direct form data
  leadData = {
    phoneNumber: body.phone || body.mobile || '',
    name: body.name || body.full_name || 'Lead',
    email: body.email || '',
    interestedIn: body.interested_in || body.property_type || 'General Inquiry',
    budget: body.budget || '',
    source: 'meta_ads',
    adName: body.ad_name || 'Meta Ad',
    timestamp: new Date().toISOString()
  };
}

return [{ json: leadData }];

// Parse Voice Call webhook (VAPI/Twilio/custom)
const body = $input.first().json.body || $input.first().json;

const callData = {
  phoneNumber: body.from || body.callerNumber || body.caller_number || '',
  transcript: body.transcript || body.message || body.text || '',
  callId: body.call_id || body.callSid || `call_${Date.now()}`,
  callStatus: body.status || 'in_progress',
  source: 'voice_call',
  sessionId: `voice_${body.from || Date.now()}`,
  timestamp: new Date().toISOString()
};

return [{ json: callData }];

// Route to correct agent based on input source
const items = $input.all();
const results = [];

for (const item of items) {
  const data = item.json;

  // Normalize input for AI agent
  results.push({
    json: {
      sessionId: data.sessionId || `session_${data.phoneNumber || Date.now()}`,
      input: data.message || data.transcript || 
             `Naya lead aaya hai Meta Ads se. Client ka naam: ${data.name || 'Unknown'}. Phone: ${data.phoneNumber}. Interested in: ${data.interestedIn || 'Property'}. Budget: ${data.budget || 'Not specified'}. Please greet them and understand their requirements.`,
      phoneNumber: data.phoneNumber || '',
      clientName: data.contactName || data.name || 'Client',
      source: data.source || 'unknown',
      isNewLead: data.source === 'meta_ads',
      timestamp: data.timestamp || new Date().toISOString()
    }
  });
}

return results;

// Extract AI response and prepare WhatsApp reply
const agentOutput = $input.first().json.output || $input.first().json.text || '';
const sessionId = $input.first().json.sessionId || '';
const phoneNumber = sessionId.replace('wa_', '').replace('voice_', '');

// Check if booking was made in the conversation
const bookingMade = agentOutput.toLowerCase().includes('booking confirm') || 
                    agentOutput.toLowerCase().includes('broker assign') ||
                    agentOutput.toLowerCase().includes('site visit scheduled');

return [{
  json: {
    phoneNumber,
    message: agentOutput,
    sessionId,
    bookingMade,
    timestamp: new Date().toISOString()
  }
}];

// Round-robin broker assignment logic
const brokers = [
  { name: 'Rajesh Kumar', telegramId: '-100BROKER_CHAT_ID_1', phone: '+91XXXXXXXXXX', specialty: 'Residential' },
  { name: 'Sunil Sharma', telegramId: '-100BROKER_CHAT_ID_2', phone: '+91XXXXXXXXXX', specialty: 'Commercial' },
  { name: 'Meena Verma', telegramId: '-100BROKER_CHAT_ID_3', phone: '+91XXXXXXXXXX', specialty: 'Plots' }
];

const data = $input.first().json;

// Simple round-robin (in production, use Supabase/DB counter)
const brokerIndex = Math.floor(Date.now() / 1000) % brokers.length;
const assignedBroker = brokers[brokerIndex];

// Select broker based on property type
const propertyName = (data.propertyName || '').toLowerCase();
let selectedBroker = assignedBroker;

if (propertyName.includes('commercial') || propertyName.includes('shop') || propertyName.includes('office')) {
  selectedBroker = brokers[1]; // Sunil for commercial
} else if (propertyName.includes('plot') || propertyName.includes('land')) {
  selectedBroker = brokers[2]; // Meena for plots
} else {
  selectedBroker = brokers[0]; // Rajesh for residential
}

const telegramMessage = `🏡 *NEW BOOKING LEAD ASSIGNED TO YOU*

👤 *Client:* ${data.clientName || 'Unknown'}
📱 *Phone:* ${data.phoneNumber}
🏠 *Property Interest:* ${data.propertyName || 'Not specified'}
💰 *Budget:* ${data.budget || 'Not specified'}
📅 *Site Visit:* ${data.visitDate || 'TBD'}
📍 *Source:* ${data.source || 'WhatsApp'}
⏰ *Time:* ${new Date().toLocaleString('en-IN', { timeZone: 'Asia/Kolkata' })}

✅ Please contact the client within 30 minutes!
💬 WhatsApp them directly: https://wa.me/${(data.phoneNumber || '').replace('+', '')}`;

return [{
  json: {
    ...data,
    brokerName: selectedBroker.name,
    brokerPhone: selectedBroker.phone,
    brokerTelegramId: selectedBroker.telegramId,
    telegramMessage,
    bookingDate: new Date().toISOString()
  }
}];

// Generate personalized follow-up messages
const items = $input.all();
const results = [];

const followUpTemplates = [
  // Follow-up 1 (first follow-up)
  (name, property) => `Namaste ${name}! 🙏

Aapne hamare saath property dekhne mein interest dikhaya tha. Kya aap abhi available hain?

🏡 ${property || 'Hamare paas kai behtareen properties available hain'}

Khushqi se aapki madad karenge! Reply karein ya call karein. 😊

- Prime Realty Team`,

  // Follow-up 2 (second follow-up)
  (name, property) => `Hello ${name}! 👋

Aaj hamare paas ek special offer hai! 🎉

✨ Free Site Visit
✨ Home Loan Assistance
✨ Legal Verification Free

${property ? `Aapke pasand ki property: *${property}* abhi bhi available hai!` : 'Best deals pe baat karein!'}

Aaj hi reply karein - limited slots available! 📞`,

  // Follow-up 3 (final follow-up)
  (name, property) => `Ek aakhri baar ${name} ji! 🙏

Hum samajhte hain aap busy hain. Jab bhi time mile, hum available hain.

📞 Seedha call karein: [YOUR_COMPANY_PHONE]
🌐 Website: [YOUR_WEBSITE]

Aapke sapnon ka ghar dhundhne mein hamara commitment hai! 🏡

- Prime Realty Team
(Agar interested nahi hain to yeh message ignore karein)`
];

for (const item of items) {
  const followUpCount = Number(item.json['Follow Up Count'] || 0);
  const templateFn = followUpTemplates[Math.min(followUpCount, 2)];
  const message = templateFn(
    item.json['Client Name'] || 'Ji',
    item.json['Property Interest'] || ''
  );

  results.push({
    json: {
      ...item.json,
      followUpMessage: message,
      newFollowUpCount: followUpCount + 1,
      rowIndex: item.json.$rowNumber || item.json.rowNumber
    }
  });
}

return results;

// Prepare voice call response for VAPI
const agentOutput = $input.first().json.output || 'Namaste! Main aapki kaise madad kar sakta hoon?';

// Format for VAPI response
return [{
  json: {
    response: agentOutput,
    timestamp: new Date().toISOString()
  }
}];
